static int srmcons_open ( struct tty_struct * tty , struct file * filp ) { struct srmcons_private * srmconsp = & srmcons_singleton ; struct tty_port * port = & srmconsp -> port ; unsigned long flags ; spin_lock_irqsave ( & port -> lock , flags ) ; if ( ! port -> tty ) { tty -> driver_data = srmconsp ; tty -> port = port ; port -> tty = tty ; } spin_unlock_irqrestore ( & port -> lock , flags ) ; return 0 ; } 